from pathlib import Path
import ast, json

src = Path('/inputs')
out = Path('/work/layout.json')
# Read the required reference strictly as inert UTF-8 text.
_ = (src / 'smell-catalog.md').read_text(encoding='utf-8')

paths = sorted(
    (p for p in src.iterdir()
     if p.is_file() and p.suffix == '.py'
     and p.name != '__init__.py'
     and not p.name.startswith('test_')
     and not p.name.endswith('_test.py')),
    key=lambda p: p.name,
)
by_stem = {p.stem: p.name for p in paths}
included = set(by_stem)
line_counts = {}
graph = {}

for p in paths:
    text = p.read_text(encoding='utf-8')
    line_counts[p.name] = len(text.splitlines())
    tree = ast.parse(text, filename=str(p))
    edges = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                parts = alias.name.split('.')
                if len(parts) >= 3 and parts[:2] == ['skillc', 'frontend']:
                    candidate = parts[2]
                    if candidate in included and candidate != p.stem:
                        edges.add(by_stem[candidate])
        elif isinstance(node, ast.ImportFrom):
            candidate_names = []
            if node.level == 1:
                if node.module:
                    candidate_names.append(node.module.split('.')[0])
                else:
                    candidate_names.extend(a.name.split('.')[0] for a in node.names if a.name != '*')
            elif node.level == 0 and node.module:
                parts = node.module.split('.')
                if parts == ['skillc', 'frontend']:
                    candidate_names.extend(a.name.split('.')[0] for a in node.names if a.name != '*')
                elif len(parts) >= 3 and parts[:2] == ['skillc', 'frontend']:
                    candidate_names.append(parts[2])
            # level > 1 and all other imports are intentionally ignored
            for candidate in candidate_names:
                if candidate in included and candidate != p.stem:
                    edges.add(by_stem[candidate])
    graph[p.name] = sorted(edges)

files = [
    {'name': p.name, 'lines': line_counts[p.name], 'imports': graph[p.name]}
    for p in paths
]

# Generate every qualifying prefix member set, then collapse equal sets.
stems = sorted(included)
member_sets = set()
for stem in stems:
    for n in range(4, len(stem) + 1):
        prefix = stem[:n]
        members = frozenset(s for s in stems if s.startswith(prefix))
        if len(members) >= 3:
            member_sets.add(members)

def lcp(strings):
    ordered = sorted(strings)
    a, b = ordered[0], ordered[-1]
    i = 0
    while i < min(len(a), len(b)) and a[i] == b[i]:
        i += 1
    return a[:i]

prefix_clusters = []
for members in member_sets:
    names = sorted(by_stem[s] for s in members)
    prefix_clusters.append({
        'prefix': lcp(members),
        'files': names,
        'lines': sum(line_counts[n] for n in names),
    })
prefix_clusters.sort(key=lambda r: r['prefix'])

import_tree_clusters = []
for root_name in sorted(graph):
    if len(graph[root_name]) < 3:
        continue
    seen = set()
    stack = [root_name]
    while stack:
        cur = stack.pop()
        if cur in seen:
            continue
        seen.add(cur)
        stack.extend(graph[cur])
    if len(seen) >= 5:
        names = sorted(seen)
        import_tree_clusters.append({
            'root': root_name,
            'files': names,
            'lines': sum(line_counts[n] for n in names),
        })
import_tree_clusters.sort(key=lambda r: r['root'])

result = {
    'files': files,
    'prefix_clusters': prefix_clusters,
    'import_tree_clusters': import_tree_clusters,
}
out.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(f'wrote {out}: {out.stat().st_size} bytes')
print(f'files={len(files)} prefix_clusters={len(prefix_clusters)} import_tree_clusters={len(import_tree_clusters)}')
print(out.read_text(encoding='utf-8'))
